<script setup lang="ts">
import { useForm } from '@inertiajs/vue3';import { watch,computed } from 'vue';import type { Incident,Workspace } from '../types';import AppModal from './AppModal.vue';import FormErrors from './FormErrors.vue';
const props=defineProps<{open:boolean;incident:Incident|null;action:string;workspace:Workspace}>();const emit=defineEmits<{close:[]}>();
const form=useForm({action:'log',notes:'',status:'in_progress',assigned_to:'',cause:'',work:'',restored_at:'',prevention:'',confirmed:false,signed_document_url:'',proofs:[] as File[]});
const people=computed(()=>props.workspace.people.filter(p=>p.role==='admin'||p.all_branches||p.branches.some(b=>b.id===props.incident?.branch_id)));
watch(()=>props.open,open=>{if(!open)return;form.reset();form.clearErrors();form.action=props.action;form.assigned_to=String(props.incident?.assigned_to||'');form.signed_document_url=props.incident?.signed_document_url||'';form.status=['assigned','in_progress','on_hold'].includes(props.incident?.status||'')?props.incident!.status:'in_progress';});
function save(){if(!props.incident)return;form.transform(data=>({...data,restored_at:data.restored_at?`${data.restored_at}:00+08:00`:''})).post(`/incidents/${props.incident.id}/actions`,{forceFormData:true,onSuccess:()=>emit('close'),preserveScroll:true});}
</script>
<template><AppModal :open="open" :title="{log:'Add action log',resolve:'Resolve incident',verify:'Verify and close',reopen:'Reopen incident',document:'Signed incident document'}[action]||'Update incident'" :busy="form.processing" @close="emit('close')"><form @submit.prevent="save"><p>{{incident?.reference}} · {{incident?.title}}</p><FormErrors :errors="form.errors"/><div v-if="action==='log'" class="rw-form-grid"><label>Status<select v-model="form.status"><option value="assigned">Assigned</option><option value="in_progress">In progress</option><option value="on_hold">On hold</option></select></label><label>Assign to<select v-model="form.assigned_to"><option value="">Unassigned</option><option v-for="p in people" :key="p.id" :value="String(p.id)">{{p.name}}</option></select></label></div><template v-if="action==='resolve'"><label>Root cause *<textarea v-model="form.cause" required maxlength="2000"></textarea></label><label>Work performed *<textarea v-model="form.work" required maxlength="4000"></textarea></label><label>Service restored at (Philippine time) *<input v-model="form.restored_at" type="datetime-local" required></label><label>Preventive action<textarea v-model="form.prevention" maxlength="2000"></textarea></label></template><label v-if="action==='document'">Signed report document URL<input v-model="form.signed_document_url" type="url" maxlength="2000"><small>Leave blank to remove the link. The document stays in your document storage.</small></label><label>{{action==='verify'?'Verification notes':action==='document'?'Reason for updating the link':'Action / findings'}} *<textarea v-model="form.notes" required maxlength="4000"></textarea></label><label v-if="['resolve','verify'].includes(action)" class="rw-check"><input v-model="form.confirmed" type="checkbox" required>I have checked the service and confirm {{action==='resolve'?'restoration.':'this resolution.'}}</label><label v-if="action!=='document'">Attach proof (up to 3 images or PDFs)<input type="file" multiple accept=".jpg,.jpeg,.png,.webp,.pdf" @change="form.proofs=Array.from(($event.target as HTMLInputElement).files||[])"></label><p v-if="form.proofs.length">{{form.proofs.length}} files selected · up to 8 MB each</p><div class="rw-form-actions"><button type="button" class="rw-btn" :disabled="form.processing" @click="emit('close')">Cancel</button><button class="rw-btn primary" :disabled="form.processing">{{form.processing?'Saving…':'Save incident update'}}</button></div></form></AppModal></template>
